//! The material a terrain wears before it has a Surface: the engine's blockout
//! grid, the same one every untextured shape wears.
//!
//! A shape's grid comes from its box-projected UVs. A terrain chunk's UVs run
//! 0..1 across the chunk, so here the grid is projected from world position in
//! the shader instead, one tile per metre like the shapes, along whichever axis
//! a face points (so the perimeter walls are ruled too, not smeared).
//!
//! The grid images are generated by the engine at startup
//! (`renzora::core::GridTexture`). A material created before they exist, or in
//! a crate that cannot see them, is given them by [`fill_grid_textures`]; until
//! then it draws as the plain tint.

use bevy::pbr::{Material, MaterialPlugin};
use bevy::prelude::*;
use bevy::render::render_resource::AsBindGroup;
use bevy::shader::ShaderRef;
use renzora::core::GridTexture;

pub struct TerrainMaterialPlugin;

impl Plugin for TerrainMaterialPlugin {
    fn build(&self, app: &mut App) {
        bevy::asset::embedded_asset!(app, "shaders/terrain_checkerboard.wesl");
        app.add_plugins(MaterialPlugin::<TerrainCheckerboardMaterial>::default())
            .add_systems(PostUpdate, fill_grid_textures);
    }
}

/// The blockout grid, projected from world position. The type keeps its old
/// name: scenes and the viewport's debug views refer to it by type.
#[derive(Asset, TypePath, AsBindGroup, Debug, Clone)]
pub struct TerrainCheckerboardMaterial {
    /// Multiplies the grid, as a shape's colour does.
    #[uniform(0)]
    pub tint: LinearRgba,
    /// x = grid tiles per metre, y = metallic, z = roughness, w = 1 when the
    /// grid images are bound (0 draws the plain tint).
    #[uniform(0)]
    pub properties: Vec4,
    #[texture(1)]
    #[sampler(2)]
    pub grid_color: Option<Handle<Image>>,
    /// The line grooves the shapes' grid is cut with.
    #[texture(3)]
    pub grid_normal: Option<Handle<Image>>,
}

impl Default for TerrainCheckerboardMaterial {
    /// The Plane shape's grey and the blockout roughness, so a fresh terrain
    /// reads as the same material as a fresh plane beside it.
    fn default() -> Self {
        Self {
            tint: Color::srgb(0.35, 0.35, 0.35).into(),
            properties: Vec4::new(1.0, 0.0, 0.4, 0.0),
            grid_color: None,
            grid_normal: None,
        }
    }
}

impl Material for TerrainCheckerboardMaterial {
    fn fragment_shader() -> ShaderRef {
        "embedded://renzora_terrain/shaders/terrain_checkerboard.wesl".into()
    }

    fn alpha_mode(&self) -> AlphaMode {
        AlphaMode::Opaque
    }
}

/// Give every terrain grid material the engine's grid images once they exist.
fn fill_grid_textures(
    grid: Option<Res<GridTexture>>,
    mut events: MessageReader<AssetEvent<TerrainCheckerboardMaterial>>,
    mut materials: ResMut<Assets<TerrainCheckerboardMaterial>>,
    mut pending: Local<Vec<AssetId<TerrainCheckerboardMaterial>>>,
) {
    pending.extend(events.read().filter_map(|e| match e {
        AssetEvent::Added { id } => Some(*id),
        _ => None,
    }));
    let Some(grid) = grid else { return };
    for id in pending.drain(..) {
        if let Some(mut material) = materials.get_mut(id) {
            if material.grid_color.is_none() {
                material.grid_color = Some(grid.color.clone());
                material.grid_normal = Some(grid.normal.clone());
                material.properties.w = 1.0;
            }
        }
    }
}
